### Access dynamic route segments in static builds with params

Source: https://github.com/withastro/docs/blob/main/src/content/docs/en/reference/api-reference.mdx

Retrieve dynamic route parameters defined in getStaticPaths() for prerendered routes. Use Astro.params in pages or context.params in endpoints.

```astro
---
export function getStaticPaths() {
  return [
    { params: { id: '1' } },
    { params: { id: '2' } },
    { params: { id: '3' } }
  ];
}
const { id } = Astro.params;
---
<h1>{id}</h1>
```

```ts
import type { APIContext } from 'astro';

export function getStaticPaths() {
  return [
    { params: { id: '1' } },
    { params: { id: '2' } },
    { params: { id: '3' } }
  ];
}

export function GET({ params }: APIContext) {
  return new Response(
    JSON.stringify({ id: params.id }),
  );
}
```

