### Define dynamic routes using getStaticPaths in Astro

Source: https://github.com/withastro/docs/blob/main/src/content/docs/en/guides/migrate-to-astro/from-nuxtjs.mdx

Export `getStaticPaths()` in the frontmatter of a dynamic page to generate static routes with path parameters.

```astro
---
export const getStaticPaths = async () => {
  const res = await fetch("https://pokeapi.co/api/v2/pokemon?limit=151");
  const resJson = await res.json();
  const pokemons = resJson.results;
  return pokemons.map((pokemon: any) => ({
    params: { name: pokemon.name },
  }));
};
// ...
---

<!-- Your template here -->
```

